<?php require_once __DIR__ . '/lib/functions.php'; if (current_user()) redirect('dashboard.php'); $errors=[]; if ($_SERVER['REQUEST_METHOD']==='POST'){ csrf_check(); $u=trim($_POST['userid']??''); $p=(string)($_POST['password']??''); $p2=(string)($_POST['password2']??''); $email=trim($_POST['email']??''); $sex=($_POST['sex']??'M')==='F'?'F':'M'; $birth=$_POST['birthdate']??null; if(!preg_match('/^[A-Za-z0-9_]{4,23}$/',$u))$errors[]='Game ID ต้องมี 4-23 ตัว และใช้ A-Z, 0-9 หรือ _'; if(strlen($p)<4||strlen($p)>23)$errors[]='รหัสผ่านต้องมี 4-23 ตัว'; if($p!==$p2)$errors[]='ยืนยันรหัสผ่านไม่ตรงกัน'; if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='อีเมลไม่ถูกต้อง'; if(account_exists($u))$errors[]='Game ID นี้ถูกใช้งานแล้ว'; if(!$errors){ $pdo=db(); $nextId=(int)$pdo->query("SELECT GREATEST(2000000, COALESCE(MAX(account_id)+1, 2000000)) FROM login WHERE sex<>'S'")->fetchColumn(); $st=$pdo->prepare("INSERT INTO login(account_id,userid,user_pass,sex,email,birthdate) VALUES(?,?,?,?,?,?)"); try { $st->execute([$nextId,$u,$p,$sex,$email,$birth?:null]); flash('success','สมัครสมาชิกเรียบร้อยแล้ว สามารถเข้าสู่ระบบได้'); redirect('login.php'); } catch(PDOException $e){ if((string)$e->getCode()==='23000'){ $errors[]='Game ID นี้ถูกใช้งานแล้ว กรุณาลองใหม่'; } else { throw $e; } } }} require __DIR__.'/partials/header.php'; ?>
<section class="auth-wrap"><form class="auth-card" method="post"><span class="eyebrow">CREATE ACCOUNT</span><h1>สมัครสมาชิก</h1><p>สร้าง Game ID สำหรับเข้าเล่น JUTI Ragnarok</p><?php foreach($errors as $er): ?><div class="form-error"><?= e($er) ?></div><?php endforeach; ?><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Game ID<input name="userid" maxlength="23" required value="<?= e($_POST['userid']??'') ?>"></label><label>Password<input type="password" name="password" maxlength="23" required></label><label>Confirm Password<input type="password" name="password2" maxlength="23" required></label><label>Email<input type="email" name="email" required value="<?= e($_POST['email']??'') ?>"></label><div class="form-row"><label>Gender<select name="sex"><option value="M">Male</option><option value="F">Female</option></select></label><label>Birthdate<input type="date" name="birthdate"></label></div><button class="btn primary wide">ลงทะเบียน</button><small>มีบัญชีแล้ว? <a href="login.php">เข้าสู่ระบบ</a></small></form></section>
<?php require __DIR__.'/partials/footer.php'; ?>
